    base_stock = 160.41846094220386  # OPT_PARAM: {"initial": 160.41846094220386, "min": 100, "max": 300, "type": "float"}
    safety_stock = 48.34932238477587  # OPT_PARAM: {"initial": 48.34932238477587, "min": 20, "max": 150, "type": "float"}
    demand_estimate = 108.9501595869336  # OPT_PARAM: {"initial": 108.9501595869336, "min": 70, "max": 200, "type": "float"}
    smoothing_factor = 0.2992448162409029  # OPT_PARAM: {"initial": 0.2992448162409029, "min": 0.1, "max": 1.0, "type": "float"}
    lead_time_multiplier = 1.3080461650300093  # OPT_PARAM: {"initial": 1.3080461650300093, "min": 0.5, "max": 2.0, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate expected demand during lead time with multiplier
    lead_time = len(pipeline_orders)
    expected_demand_during_lead_time = demand_estimate * lead_time * lead_time_multiplier

