    deficit_factor = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.5, "max": 1.0, "type": "float"}
    smoothing_factor = 0.5  # OPT_PARAM: {"initial": 0.5, "min": 0.1, "max": 0.5, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Adjust target based on pipeline variability
    if len(pipeline_orders) > 1:
        pipeline_range = max(pipeline_orders) - min(pipeline_orders)
        pipeline_adjustment = pipeline_range * pipeline_weight
    else:
        pipeline_adjustment = 0

    # Target inventory level
    target_inventory = base_stock + safety_stock + pipeline_adjustment

    # Calculate order needed to reach target
    order_needed = max(0, target_inventory - inventory_position)

    # Apply deficit factor
    order_amount = order_needed * deficit_factor

    # Smooth with demand estimate and previous order smoothing
    if order_amount > 0:
        smoothed_order = (order_amount * (1 - smoothing_factor) + 
                         demand_estimate * smoothing_factor)
        order_amount = max(smoothed_order, demand_estimate * 0.5)

    # Round to integer
    return order_amount

