    # Calculate net inventory position
    net_inventory = on_hand_inventory + sum(pipeline_orders)

    # Estimate upcoming demand based on recent pipeline arrivals
    # (pipeline_orders[0] arrived today, pipeline_orders[1] arrives tomorrow, etc.)
    if len(pipeline_orders) >= 2:
        # Use average of recent arrivals as demand proxy
        recent_arrivals = pipeline_orders[:min(3, len(pipeline_orders))]
        avg_recent = sum(recent_arrivals) / len(recent_arrivals)
        demand_estimate = avg_recent * demand_forecast_factor
    else:
        demand_estimate = 0

    # Adjust base stock level based on demand estimate
    adjusted_base_stock = base_stock + demand_estimate

    # Calculate order-up-to level with safety stock
    order_up_to = max(adjusted_base_stock, safety_stock)

    # Order amount considering both net inventory and safety stock
    order_amount = max(0, order_up_to - net_inventory)

    # Smooth ordering by limiting large changes
    max_order_increase = 50.0  # OPT_PARAM: {"initial": 50.0, "min": 50, "max": 500, "type": "float"}
    if len(pipeline_orders) > 0:
        last_order = pipeline_orders[-1]
        if order_amount > last_order + max_order_increase:
            order_amount = last_order + max_order_increase

    return order_amount

