    for i in range(L):
        if i < 2:  # Arriving in next 2 periods
            discounted_pipeline += pipeline_orders[i] * early_discount
        elif i < 4:  # Arriving in periods 3-4
            discounted_pipeline += pipeline_orders[i] * mid_discount
        else:  # Arriving in periods 5-6
            discounted_pipeline += pipeline_orders[i] * late_discount

def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 840.9620595232684  # OPT_PARAM: {"initial": 840.9620595232684, "min": 700, "max": 1000, "type": "float"}
    safety_stock = 170.47856675888184  # OPT_PARAM: {"initial": 170.47856675888184, "min": 150, "max": 300, "type": "float"}
    demand_estimate = 89.5202867374274  # OPT_PARAM: {"initial": 89.5202867374274, "min": 85, "max": 105, "type": "float"}
    smoothing_factor = 0.05  # OPT_PARAM: {"initial": 0.05, "min": 0.05, "max": 0.3, "type": "float"}
    order_multiplier = 1.0  # OPT_PARAM: {"initial": 1.0, "min": 1.0, "max": 1.2, "type": "float"}
    pipeline_weight = 0.8  # OPT_PARAM: {"initial": 0.8, "min": 0.5, "max": 0.9, "type": "float"}
    min_order_threshold = 15.0  # OPT_PARAM: {"initial": 15.0, "min": 5, "max": 30, "type": "float"}

    # Calculate inventory position
    inventory_position = on_hand_inventory + sum(pipeline_orders)

    # Calculate weighted pipeline contribution
    weighted_pipeline = pipeline_weight * sum(pipeline_orders)

    # Calculate expected demand during lead time with multiplier
    lead_time = len(pipeline_orders)
    expected_lead_time_demand = demand_estimate * lead_time * order_multiplier

    # Calculate target inventory position
    target_position = expected_lead_time_demand + safety_stock

    # Calculate order amount with pipeline consideration
    raw_order = max(0, target_position - (on_hand_inventory + weighted_pipeline))

    # Apply smoothing
    smoothed_order = smoothing_factor * raw_order + (1 - smoothing_factor) * demand_estimate

    # Apply base stock constraint
    order_amount = min(smoothed_order, max(0, base_stock - inventory_position))

    # Apply minimum order threshold
    if order_amount < min_order_threshold:
        order_amount = 0

