def compute_order_amount(on_hand_inventory, pipeline_orders):
    base_stock = 274.67527773039234  # OPT_PARAM: {"initial": 274.67527773039234, "min": 200, "max": 350, "type": "float"}
    pipeline_coverage = 0.7  # OPT_PARAM: {"initial": 0.7, "min": 0.7, "max": 1.0, "type": "float"}
    safety_multiplier = 1.3  # OPT_PARAM: {"initial": 1.3, "min": 1.2, "max": 2.5, "type": "float"}
    demand_buffer = 0.9  # OPT_PARAM: {"initial": 0.9, "min": 0.9, "max": 1.3, "type": "float"}
    pipeline_weight = 0.9  # OPT_PARAM: {"initial": 0.9, "min": 0.5, "max": 0.9, "type": "float"}
    smoothing_factor = 0.3  # OPT_PARAM: {"initial": 0.3, "min": 0.3, "max": 0.8, "type": "float"}

    # Calculate weighted pipeline with exponential decay
    weighted_pipeline = 0
    for i, q in enumerate(pipeline_orders):
        weight = pipeline_weight ** (len(pipeline_orders) - i - 1)
        weighted_pipeline += q * weight

    # Calculate effective inventory position
    effective_inventory = on_hand_inventory + weighted_pipeline

    # Calculate target inventory position
    target_inventory = base_stock * demand_buffer

    # Calculate expected shortfall with pipeline coverage adjustment
    expected_shortfall = max(0, target_inventory * pipeline_coverage - effective_inventory)

    # Dynamic safety stock based on base stock
    safety_component = base_stock * 0.15 * safety_multiplier

    # Calculate order amount with exponential smoothing
    order_amount = max(0, expected_shortfall * smoothing_factor + safety_component)

    # Round to nearest integer
    order_amount = int(round(order_amount))

    return order_amount
